<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../api';const organizations=ref<any[]>([]),organizationId=ref(''),data=ref<any>(null),features=ref<any[]>([]),loading=ref(false),saving=ref(false),error=ref('');async function boot(){try{organizations.value=(await api('/tk-api/enterprise/platform/tenants')).tenants;if(organizations.value.length){organizationId.value=String(organizations.value[0].id);await load()}}catch(e:any){error.value=e.message}}async function load(){if(!organizationId.value)return;loading.value=true;error.value='';try{data.value=await api(`/api/v2/platform/organizations/${organizationId.value}/features`);features.value=Object.entries(data.value?.features||{}).map(([code,value])=>({code,...(value as any)}))}catch(e:any){error.value=e.message}finally{loading.value=false}}async function save(){if(!data.value)return;if(!window.confirm('保存后将立即影响该企业可使用的功能，并触发客户端刷新配置。确认继续吗？'))return;saving.value=true;try{await api(`/api/v2/platform/organizations/${organizationId.value}/features`,{method:'PUT',body:JSON.stringify({items:features.value.map(x=>({feature_code:x.code,enabled:x.enabled,source:'manual'}))})});await load()}catch(e:any){error.value=e.message}finally{saving.value=false}}onMounted(boot);</script>
<template><section class="panel"><header class="panel-head"><div><span class="eyebrow">ORGANIZATION ENTITLEMENTS</span><h2>企业功能授权</h2><p>平台管理员可以给企业开通试用、手动关闭功能或恢复套餐配置。</p></div><button class="primary" :disabled="saving||!data" @click="save">{{saving?'正在保存…':'保存授权'}}</button></header><div class="toolbar"><select v-model="organizationId" @change="load"><option value="" disabled>选择企业</option><option v-for="x in organizations" :key="x.id" :value="String(x.id)">{{x.name}}</option></select><span v-if="data" class="quota">配置版本 {{data.config_version}}</span></div><div v-if="loading" class="state-inline">正在获取企业功能……</div><div v-else-if="error" class="state-inline error"><b>暂时无法加载授权</b><span>{{error}}</span><button @click="load">立即重试</button></div><div v-else-if="!features.length" class="empty-state">请选择企业查看功能授权。</div><div v-else class="entitlement-list"><label v-for="x in features" :key="x.code"><input v-model="x.enabled" type="checkbox"><span><b>{{x.name}}</b><small>{{x.code}} · 当前来源 {{x.source}}</small></span><em>{{x.enabled?'已开通':'未开通'}}</em></label></div></section></template>
